___CSS_LOADER_EXPORT___.push([module.id, `/* BookingPage — Eigenständige Termin-Seite (Pre-Login) */

.bp-root {
  min-height: 100vh;
  background: var(--nx-bg, #0c1117);
  color: #fff;
  font-family: var(--f-body, 'Inter', sans-serif);
  display: flex;
  flex-direction: column;
}

/* Nav */
.bp-nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(12, 17, 23, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(255,255,255,0.04);
}
.bp-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.bp-logo {
  text-decoration: none;
  color: #fff;
}
.bp-back-link {
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgba(255,255,255,0.4);
  font-size: .8125rem;
  font-weight: 600;
  text-decoration: none;
  transition: color 200ms;
}
.bp-back-link:hover { color: rgba(255,255,255,0.8); }
.bp-back-link .material-symbols-outlined { font-size: 16px; }

/* Layout */
.bp-layout {
  flex: 1 1;
  max-width: 1200px;
  margin: 0 auto;
  padding: 48px 24px 64px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: start;
}

/* Left Info Column */
.bp-info { position: sticky; top: 100px; }
.bp-title {
  font-family: var(--f-display, 'Inter', sans-serif);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
  margin: 0 0 12px;
}
.bp-subtitle {
  font-size: clamp(.9rem, 1.2vw, 1.05rem);
  color: rgba(255,255,255,0.5);
  line-height: 1.65;
  margin: 0 0 28px;
  max-width: 480px;
}

/* Badges */
.bp-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 32px;
}
.bp-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 20px;
  font-size: .75rem;
  font-weight: 600;
  color: rgba(255,255,255,0.5);
}
.bp-badge .material-symbols-outlined { font-size: 14px; }
.bp-badge-green { color: rgba(52,211,153,0.8); border-color: rgba(52,211,153,0.12); }
.bp-badge-green .material-symbols-outlined { color: rgba(52,211,153,0.7); }

/* Trust Section */
.bp-trust {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 36px;
  padding: 20px;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(255,255,255,0.04);
  border-radius: 12px;
}
.bp-trust-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: .8125rem;
  color: rgba(255,255,255,0.55);
}
.bp-trust-icon { font-size: 16px; color: var(--nx-accent, #FE9B7B); }

/* Expect Section */
.bp-expect { margin-bottom: 24px; }
.bp-expect-title {
  font-family: var(--f-display, 'Inter', sans-serif);
  font-size: .875rem;
  font-weight: 700;
  color: rgba(255,255,255,0.5);
  margin: 0 0 16px;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.bp-expect-item {
  display: flex;
  gap: 14px;
  margin-bottom: 16px;
}
.bp-expect-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(254,155,123,0.08);
  border: 1px solid rgba(254,155,123,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--f-display);
  font-size: .75rem;
  font-weight: 800;
  color: var(--nx-accent, #FE9B7B);
  flex-shrink: 0;
  margin-top: 2px;
}
.bp-expect-heading {
  font-weight: 700;
  font-size: .875rem;
  color: rgba(255,255,255,0.8);
  margin-bottom: 2px;
}
.bp-expect-desc {
  font-size: .8125rem;
  color: rgba(255,255,255,0.4);
  line-height: 1.5;
}

/* Card (Right Column) */
.bp-form-col { position: relative; }
.bp-card {
  background: rgba(15,21,28,0.95);
  backdrop-filter: blur(24px);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 14px;
  padding: 28px;
  box-shadow: 0 32px 80px rgba(0,0,0,0.4);
  position: sticky;
  top: 80px;
}
.bp-card-step {
  display: inline-block;
  font-size: .6875rem;
  font-weight: 700;
  color: var(--nx-accent, #FE9B7B);
  background: rgba(254,155,123,0.06);
  border: 1px solid rgba(254,155,123,0.12);
  padding: 3px 10px;
  border-radius: 12px;
  margin-bottom: 16px;
}
.bp-card-title {
  font-family: var(--f-display, 'Inter', sans-serif);
  font-size: .9375rem;
  font-weight: 700;
  color: rgba(255,255,255,0.6);
  margin: 0 0 14px;
}

/* Dates Grid */
.bp-dates {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
  margin-bottom: 20px;
}
.bp-date {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 10px 4px;
  background: rgba(12,17,23,0.5);
  border: 1px solid rgba(255,255,255,0.04);
  color: rgba(255,255,255,0.4);
  cursor: pointer;
  transition: all 250ms ease;
  border-radius: 8px;
}
.bp-date:hover {
  border-color: rgba(254,155,123,0.15);
  transform: translateY(-2px);
  color: rgba(255,255,255,0.7);
}
.bp-date.sel {
  border-color: var(--nx-accent, #FE9B7B);
  background: rgba(254,155,123,0.06);
  color: #fff;
  box-shadow: 0 0 20px rgba(254,155,123,0.06);
}
.bp-date-day { font-size: .5625rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; opacity: .6; }
.bp-date-num { font-family: var(--f-display); font-size: 1.125rem; font-weight: 800; line-height: 1.2; }
.bp-date-month { font-size: .5625rem; font-weight: 600; letter-spacing: .02em; opacity: .6; }

/* Times Grid */
.bp-times {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-bottom: 20px;
}
.bp-time {
  padding: 10px;
  background: rgba(12,17,23,0.5);
  border: 1px solid rgba(255,255,255,0.04);
  color: rgba(255,255,255,0.45);
  font-size: .875rem;
  font-weight: 600;
  font-family: var(--f-display);
  text-align: center;
  transition: all 250ms ease;
  border-radius: 6px;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.bp-time:hover { border-color: rgba(254,155,123,0.15); color: rgba(255,255,255,0.7); }
.bp-time.sel { border-color: var(--nx-accent, #FE9B7B); background: rgba(254,155,123,0.06); color: #fff; }
.bp-no-slots { color: rgba(255,255,255,0.25); font-size: .8125rem; text-align: center; padding: 16px; }

/* Back Button */
.bp-back {
  display: flex;
  align-items: center;
  gap: 4px;
  background: none;
  border: none;
  color: rgba(255,255,255,0.35);
  font-size: .75rem;
  font-weight: 600;
  margin-bottom: 14px;
  padding: 0;
  cursor: pointer;
  transition: color 200ms;
}
.bp-back:hover { color: rgba(255,255,255,0.7); }
.bp-back .material-symbols-outlined { font-size: 16px; }

/* Selected Summary */
.bp-selected {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 16px;
  background: rgba(254,155,123,0.04);
  border: 1px solid rgba(254,155,123,0.10);
  border-radius: 8px;
  margin-bottom: 20px;
}
.bp-selected .material-symbols-outlined { font-size: 22px; color: var(--nx-accent, #FE9B7B); }
.bp-selected strong { display: block; font-size: .8125rem; color: #fff; }
.bp-selected span { display: block; font-size: .75rem; color: rgba(255,255,255,0.4); }

/* Form Fields */
.bp-fields { display: flex; flex-direction: column; gap: 14px; }
.bp-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.bp-field { display: flex; flex-direction: column; gap: 4px; }
.bp-field label {
  font-size: .625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--nx-accent, #FE9B7B);
}
.bp-field input, .bp-field textarea {
  background: rgba(14,20,28,0.7);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 6px;
  padding: 11px 14px;
  color: #fff;
  font-size: .875rem;
  font-family: var(--f-body, 'Inter', sans-serif);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  width: 100%;
  resize: vertical;
}
.bp-field input:focus, .bp-field textarea:focus {
  border-color: rgba(254,155,123,0.35);
  box-shadow: 0 0 0 3px rgba(254,155,123,0.06);
}
.bp-field input.err { border-color: #ef4444; }
.bp-err { color: #ef4444; font-size: .6875rem; font-weight: 600; }
.bp-submit-err {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: rgba(239,68,68,0.06);
  border: 1px solid rgba(239,68,68,0.15);
  border-radius: 8px;
  color: #ef4444;
  font-size: .8125rem;
}

/* Buttons */
.bp-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px 24px;
  border: none;
  border-radius: 8px;
  font-size: .9375rem;
  font-weight: 700;
  font-family: var(--f-display, 'Inter', sans-serif);
  cursor: pointer;
  transition: all 300ms ease;
  text-decoration: none;
  text-align: center;
}
.bp-btn-primary {
  background: var(--nx-accent, #FE9B7B);
  color: #0c1117;
}
.bp-btn-primary:hover:not(:disabled) {
  filter: brightness(1.1);
  transform: translateY(-1px);
  box-shadow: 0 8px 32px rgba(254,155,123,0.2);
}
.bp-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.bp-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(12,17,23,0.2);
  border-top-color: #0c1117;
  border-radius: 50%;
  animation: bp-spin .7s linear infinite;
  margin-right: 6px;
}
@keyframes bp-spin { to { transform: rotate(360deg); } }

/* Success */
.bp-success { text-align: center; padding: 24px 0; }
.bp-success-icon { margin-bottom: 16px; }
.bp-success-icon .material-symbols-outlined { font-size: 56px; color: #34d399; }
.bp-success h2 {
  font-family: var(--f-display);
  font-size: 1.5rem;
  font-weight: 800;
  margin: 0 0 20px;
}
.bp-success-detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
  padding: 16px;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(255,255,255,0.04);
  border-radius: 10px;
}
.bp-success-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: .875rem;
  color: rgba(255,255,255,0.6);
}
.bp-success-row .material-symbols-outlined { font-size: 18px; color: var(--nx-accent, #FE9B7B); }
.bp-success-text {
  font-size: .875rem;
  color: rgba(255,255,255,0.45);
  line-height: 1.6;
  margin-bottom: 20px;
}
.bp-success-next {
  text-align: left;
  padding: 16px;
  background: rgba(52,211,153,0.04);
  border: 1px solid rgba(52,211,153,0.10);
  border-radius: 10px;
  margin-bottom: 24px;
}
.bp-success-next h4 {
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: rgba(52,211,153,0.8);
  margin: 0 0 10px;
}
.bp-success-next ul { list-style: none; padding: 0; margin: 0; }
.bp-success-next li {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: .8125rem;
  color: rgba(255,255,255,0.5);
  margin-bottom: 6px;
}
.bp-success-next li .material-symbols-outlined { font-size: 14px; color: rgba(52,211,153,0.7); }

/* Footer */
.bp-footer {
  border-top: 1px solid rgba(255,255,255,0.04);
  padding: 16px 24px;
  font-size: .75rem;
  color: rgba(255,255,255,0.25);
}
.bp-footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.bp-footer-links { display: flex; gap: 16px; }
.bp-footer-links a { color: rgba(255,255,255,0.3); text-decoration: none; transition: color 200ms; }
.bp-footer-links a:hover { color: rgba(255,255,255,0.6); }

/* Responsive */
@media (max-width: 900px) {
  .bp-layout {
    grid-template-columns: 1fr;
    gap: 32px;
    padding: 32px 20px 48px;
  }
  .bp-info { position: static; }
  .bp-card { position: static; }
  .bp-dates { grid-template-columns: repeat(4, 1fr); }
}
@media (max-width: 480px) {
  .bp-layout { padding: 24px 16px 40px; }
  .bp-dates { grid-template-columns: repeat(3, 1fr); }
  .bp-times { grid-template-columns: repeat(2, 1fr); }
  .bp-row { grid-template-columns: 1fr; }
  .bp-card { padding: 20px; }
}
`, "",{"version":3,"sources":["webpack://./src/pages/BookingPage.css"],"names":[],"mappings":"AAAA,yDAAyD;;AAEzD;EACE,iBAAiB;EACjB,iCAAiC;EACjC,WAAW;EACX,+CAA+C;EAC/C,aAAa;EACb,sBAAsB;AACxB;;AAEA,QAAQ;AACR;EACE,gBAAgB;EAChB,MAAM;EACN,WAAW;EACX,kCAAkC;EAClC,2BAA2B;EAC3B,mCAAmC;EACnC,+CAA+C;AACjD;AACA;EACE,iBAAiB;EACjB,cAAc;EACd,kBAAkB;EAClB,aAAa;EACb,mBAAmB;EACnB,8BAA8B;AAChC;AACA;EACE,qBAAqB;EACrB,WAAW;AACb;AACA;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,4BAA4B;EAC5B,mBAAmB;EACnB,gBAAgB;EAChB,qBAAqB;EACrB,uBAAuB;AACzB;AACA,sBAAsB,4BAA4B,EAAE;AACpD,2CAA2C,eAAe,EAAE;;AAE5D,WAAW;AACX;EACE,SAAO;EACP,iBAAiB;EACjB,cAAc;EACd,uBAAuB;EACvB,aAAa;EACb,8BAA8B;EAC9B,SAAS;EACT,kBAAkB;AACpB;;AAEA,qBAAqB;AACrB,WAAW,gBAAgB,EAAE,UAAU,EAAE;AACzC;EACE,kDAAkD;EAClD,sCAAsC;EACtC,gBAAgB;EAChB,sBAAsB;EACtB,iBAAiB;EACjB,gBAAgB;AAClB;AACA;EACE,uCAAuC;EACvC,4BAA4B;EAC5B,iBAAiB;EACjB,gBAAgB;EAChB,gBAAgB;AAClB;;AAEA,WAAW;AACX;EACE,aAAa;EACb,eAAe;EACf,QAAQ;EACR,mBAAmB;AACrB;AACA;EACE,oBAAoB;EACpB,mBAAmB;EACnB,QAAQ;EACR,iBAAiB;EACjB,kCAAkC;EAClC,wCAAwC;EACxC,mBAAmB;EACnB,iBAAiB;EACjB,gBAAgB;EAChB,4BAA4B;AAC9B;AACA,uCAAuC,eAAe,EAAE;AACxD,kBAAkB,2BAA2B,EAAE,mCAAmC,EAAE;AACpF,6CAA6C,2BAA2B,EAAE;;AAE1E,kBAAkB;AAClB;EACE,aAAa;EACb,sBAAsB;EACtB,SAAS;EACT,mBAAmB;EACnB,aAAa;EACb,kCAAkC;EAClC,wCAAwC;EACxC,mBAAmB;AACrB;AACA;EACE,aAAa;EACb,mBAAmB;EACnB,SAAS;EACT,mBAAmB;EACnB,6BAA6B;AAC/B;AACA,iBAAiB,eAAe,EAAE,gCAAgC,EAAE;;AAEpE,mBAAmB;AACnB,aAAa,mBAAmB,EAAE;AAClC;EACE,kDAAkD;EAClD,kBAAkB;EAClB,gBAAgB;EAChB,4BAA4B;EAC5B,gBAAgB;EAChB,yBAAyB;EACzB,qBAAqB;AACvB;AACA;EACE,aAAa;EACb,SAAS;EACT,mBAAmB;AACrB;AACA;EACE,WAAW;EACX,YAAY;EACZ,kBAAkB;EAClB,kCAAkC;EAClC,wCAAwC;EACxC,aAAa;EACb,mBAAmB;EACnB,uBAAuB;EACvB,6BAA6B;EAC7B,iBAAiB;EACjB,gBAAgB;EAChB,gCAAgC;EAChC,cAAc;EACd,eAAe;AACjB;AACA;EACE,gBAAgB;EAChB,kBAAkB;EAClB,4BAA4B;EAC5B,kBAAkB;AACpB;AACA;EACE,mBAAmB;EACnB,4BAA4B;EAC5B,gBAAgB;AAClB;;AAEA,wBAAwB;AACxB,eAAe,kBAAkB,EAAE;AACnC;EACE,+BAA+B;EAC/B,2BAA2B;EAC3B,wCAAwC;EACxC,mBAAmB;EACnB,aAAa;EACb,uCAAuC;EACvC,gBAAgB;EAChB,SAAS;AACX;AACA;EACE,qBAAqB;EACrB,mBAAmB;EACnB,gBAAgB;EAChB,gCAAgC;EAChC,kCAAkC;EAClC,wCAAwC;EACxC,iBAAiB;EACjB,mBAAmB;EACnB,mBAAmB;AACrB;AACA;EACE,kDAAkD;EAClD,mBAAmB;EACnB,gBAAgB;EAChB,4BAA4B;EAC5B,gBAAgB;AAClB;;AAEA,eAAe;AACf;EACE,aAAa;EACb,qCAAqC;EACrC,QAAQ;EACR,mBAAmB;AACrB;AACA;EACE,aAAa;EACb,sBAAsB;EACtB,mBAAmB;EACnB,QAAQ;EACR,iBAAiB;EACjB,8BAA8B;EAC9B,wCAAwC;EACxC,4BAA4B;EAC5B,eAAe;EACf,0BAA0B;EAC1B,kBAAkB;AACpB;AACA;EACE,oCAAoC;EACpC,2BAA2B;EAC3B,4BAA4B;AAC9B;AACA;EACE,uCAAuC;EACvC,kCAAkC;EAClC,WAAW;EACX,2CAA2C;AAC7C;AACA,eAAe,mBAAmB,EAAE,gBAAgB,EAAE,yBAAyB,EAAE,qBAAqB,EAAE,WAAW,EAAE;AACrH,eAAe,6BAA6B,EAAE,mBAAmB,EAAE,gBAAgB,EAAE,gBAAgB,EAAE;AACvG,iBAAiB,mBAAmB,EAAE,gBAAgB,EAAE,qBAAqB,EAAE,WAAW,EAAE;;AAE5F,eAAe;AACf;EACE,aAAa;EACb,qCAAqC;EACrC,QAAQ;EACR,mBAAmB;AACrB;AACA;EACE,aAAa;EACb,8BAA8B;EAC9B,wCAAwC;EACxC,6BAA6B;EAC7B,kBAAkB;EAClB,gBAAgB;EAChB,6BAA6B;EAC7B,kBAAkB;EAClB,0BAA0B;EAC1B,kBAAkB;EAClB,eAAe;EACf,kCAAkC;AACpC;AACA,iBAAiB,oCAAoC,EAAE,4BAA4B,EAAE;AACrF,eAAe,uCAAuC,EAAE,kCAAkC,EAAE,WAAW,EAAE;AACzG,eAAe,6BAA6B,EAAE,mBAAmB,EAAE,kBAAkB,EAAE,aAAa,EAAE;;AAEtG,gBAAgB;AAChB;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,gBAAgB;EAChB,YAAY;EACZ,6BAA6B;EAC7B,iBAAiB;EACjB,gBAAgB;EAChB,mBAAmB;EACnB,UAAU;EACV,eAAe;EACf,uBAAuB;AACzB;AACA,iBAAiB,4BAA4B,EAAE;AAC/C,sCAAsC,eAAe,EAAE;;AAEvD,qBAAqB;AACrB;EACE,aAAa;EACb,mBAAmB;EACnB,SAAS;EACT,kBAAkB;EAClB,kCAAkC;EAClC,wCAAwC;EACxC,kBAAkB;EAClB,mBAAmB;AACrB;AACA,0CAA0C,eAAe,EAAE,gCAAgC,EAAE;AAC7F,sBAAsB,cAAc,EAAE,mBAAmB,EAAE,WAAW,EAAE;AACxE,oBAAoB,cAAc,EAAE,iBAAiB,EAAE,4BAA4B,EAAE;;AAErF,gBAAgB;AAChB,aAAa,aAAa,EAAE,sBAAsB,EAAE,SAAS,EAAE;AAC/D,UAAU,aAAa,EAAE,8BAA8B,EAAE,SAAS,EAAE;AACpE,YAAY,aAAa,EAAE,sBAAsB,EAAE,QAAQ,EAAE;AAC7D;EACE,kBAAkB;EAClB,gBAAgB;EAChB,yBAAyB;EACzB,oBAAoB;EACpB,gCAAgC;AAClC;AACA;EACE,8BAA8B;EAC9B,wCAAwC;EACxC,kBAAkB;EAClB,kBAAkB;EAClB,WAAW;EACX,kBAAkB;EAClB,+CAA+C;EAC/C,aAAa;EACb,8CAA8C;EAC9C,WAAW;EACX,gBAAgB;AAClB;AACA;EACE,oCAAoC;EACpC,4CAA4C;AAC9C;AACA,sBAAsB,qBAAqB,EAAE;AAC7C,UAAU,cAAc,EAAE,mBAAmB,EAAE,gBAAgB,EAAE;AACjE;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,kBAAkB;EAClB,gCAAgC;EAChC,sCAAsC;EACtC,kBAAkB;EAClB,cAAc;EACd,mBAAmB;AACrB;;AAEA,YAAY;AACZ;EACE,oBAAoB;EACpB,mBAAmB;EACnB,uBAAuB;EACvB,QAAQ;EACR,WAAW;EACX,kBAAkB;EAClB,YAAY;EACZ,kBAAkB;EAClB,mBAAmB;EACnB,gBAAgB;EAChB,kDAAkD;EAClD,eAAe;EACf,0BAA0B;EAC1B,qBAAqB;EACrB,kBAAkB;AACpB;AACA;EACE,qCAAqC;EACrC,cAAc;AAChB;AACA;EACE,uBAAuB;EACvB,2BAA2B;EAC3B,4CAA4C;AAC9C;AACA;EACE,YAAY;EACZ,mBAAmB;AACrB;AACA;EACE,WAAW;EACX,YAAY;EACZ,oCAAoC;EACpC,yBAAyB;EACzB,kBAAkB;EAClB,sCAAsC;EACtC,iBAAiB;AACnB;AACA,qBAAqB,KAAK,yBAAyB,EAAE,EAAE;;AAEvD,YAAY;AACZ,cAAc,kBAAkB,EAAE,eAAe,EAAE;AACnD,mBAAmB,mBAAmB,EAAE;AACxC,8CAA8C,eAAe,EAAE,cAAc,EAAE;AAC/E;EACE,6BAA6B;EAC7B,iBAAiB;EACjB,gBAAgB;EAChB,gBAAgB;AAClB;AACA;EACE,aAAa;EACb,sBAAsB;EACtB,QAAQ;EACR,mBAAmB;EACnB,aAAa;EACb,kCAAkC;EAClC,wCAAwC;EACxC,mBAAmB;AACrB;AACA;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,kBAAkB;EAClB,4BAA4B;AAC9B;AACA,6CAA6C,eAAe,EAAE,gCAAgC,EAAE;AAChG;EACE,kBAAkB;EAClB,6BAA6B;EAC7B,gBAAgB;EAChB,mBAAmB;AACrB;AACA;EACE,gBAAgB;EAChB,aAAa;EACb,iCAAiC;EACjC,uCAAuC;EACvC,mBAAmB;EACnB,mBAAmB;AACrB;AACA;EACE,iBAAiB;EACjB,gBAAgB;EAChB,yBAAyB;EACzB,qBAAqB;EACrB,2BAA2B;EAC3B,gBAAgB;AAClB;AACA,sBAAsB,gBAAgB,EAAE,UAAU,EAAE,SAAS,EAAE;AAC/D;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,mBAAmB;EACnB,4BAA4B;EAC5B,kBAAkB;AACpB;AACA,iDAAiD,eAAe,EAAE,2BAA2B,EAAE;;AAE/F,WAAW;AACX;EACE,4CAA4C;EAC5C,kBAAkB;EAClB,iBAAiB;EACjB,6BAA6B;AAC/B;AACA;EACE,iBAAiB;EACjB,cAAc;EACd,aAAa;EACb,8BAA8B;EAC9B,mBAAmB;EACnB,eAAe;EACf,QAAQ;AACV;AACA,mBAAmB,aAAa,EAAE,SAAS,EAAE;AAC7C,qBAAqB,4BAA4B,EAAE,qBAAqB,EAAE,uBAAuB,EAAE;AACnG,2BAA2B,4BAA4B,EAAE;;AAEzD,eAAe;AACf;EACE;IACE,0BAA0B;IAC1B,SAAS;IACT,uBAAuB;EACzB;EACA,WAAW,gBAAgB,EAAE;EAC7B,WAAW,gBAAgB,EAAE;EAC7B,YAAY,qCAAqC,EAAE;AACrD;AACA;EACE,aAAa,uBAAuB,EAAE;EACtC,YAAY,qCAAqC,EAAE;EACnD,YAAY,qCAAqC,EAAE;EACnD,UAAU,0BAA0B,EAAE;EACtC,WAAW,aAAa,EAAE;AAC5B","sourcesContent":["/* BookingPage — Eigenständige Termin-Seite (Pre-Login) */\n\n.bp-root {\n  min-height: 100vh;\n  background: var(--nx-bg, #0c1117);\n  color: #fff;\n  font-family: var(--f-body, 'Inter', sans-serif);\n  display: flex;\n  flex-direction: column;\n}\n\n/* Nav */\n.bp-nav {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  background: rgba(12, 17, 23, 0.85);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border-bottom: 1px solid rgba(255,255,255,0.04);\n}\n.bp-nav-inner {\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 14px 24px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n.bp-logo {\n  text-decoration: none;\n  color: #fff;\n}\n.bp-back-link {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  color: rgba(255,255,255,0.4);\n  font-size: .8125rem;\n  font-weight: 600;\n  text-decoration: none;\n  transition: color 200ms;\n}\n.bp-back-link:hover { color: rgba(255,255,255,0.8); }\n.bp-back-link .material-symbols-outlined { font-size: 16px; }\n\n/* Layout */\n.bp-layout {\n  flex: 1;\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 48px 24px 64px;\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 56px;\n  align-items: start;\n}\n\n/* Left Info Column */\n.bp-info { position: sticky; top: 100px; }\n.bp-title {\n  font-family: var(--f-display, 'Inter', sans-serif);\n  font-size: clamp(1.75rem, 3vw, 2.5rem);\n  font-weight: 800;\n  letter-spacing: -.03em;\n  line-height: 1.15;\n  margin: 0 0 12px;\n}\n.bp-subtitle {\n  font-size: clamp(.9rem, 1.2vw, 1.05rem);\n  color: rgba(255,255,255,0.5);\n  line-height: 1.65;\n  margin: 0 0 28px;\n  max-width: 480px;\n}\n\n/* Badges */\n.bp-badges {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-bottom: 32px;\n}\n.bp-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 6px 12px;\n  background: rgba(255,255,255,0.03);\n  border: 1px solid rgba(255,255,255,0.06);\n  border-radius: 20px;\n  font-size: .75rem;\n  font-weight: 600;\n  color: rgba(255,255,255,0.5);\n}\n.bp-badge .material-symbols-outlined { font-size: 14px; }\n.bp-badge-green { color: rgba(52,211,153,0.8); border-color: rgba(52,211,153,0.12); }\n.bp-badge-green .material-symbols-outlined { color: rgba(52,211,153,0.7); }\n\n/* Trust Section */\n.bp-trust {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  margin-bottom: 36px;\n  padding: 20px;\n  background: rgba(255,255,255,0.02);\n  border: 1px solid rgba(255,255,255,0.04);\n  border-radius: 12px;\n}\n.bp-trust-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-size: .8125rem;\n  color: rgba(255,255,255,0.55);\n}\n.bp-trust-icon { font-size: 16px; color: var(--nx-accent, #FE9B7B); }\n\n/* Expect Section */\n.bp-expect { margin-bottom: 24px; }\n.bp-expect-title {\n  font-family: var(--f-display, 'Inter', sans-serif);\n  font-size: .875rem;\n  font-weight: 700;\n  color: rgba(255,255,255,0.5);\n  margin: 0 0 16px;\n  text-transform: uppercase;\n  letter-spacing: .04em;\n}\n.bp-expect-item {\n  display: flex;\n  gap: 14px;\n  margin-bottom: 16px;\n}\n.bp-expect-num {\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  background: rgba(254,155,123,0.08);\n  border: 1px solid rgba(254,155,123,0.15);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--f-display);\n  font-size: .75rem;\n  font-weight: 800;\n  color: var(--nx-accent, #FE9B7B);\n  flex-shrink: 0;\n  margin-top: 2px;\n}\n.bp-expect-heading {\n  font-weight: 700;\n  font-size: .875rem;\n  color: rgba(255,255,255,0.8);\n  margin-bottom: 2px;\n}\n.bp-expect-desc {\n  font-size: .8125rem;\n  color: rgba(255,255,255,0.4);\n  line-height: 1.5;\n}\n\n/* Card (Right Column) */\n.bp-form-col { position: relative; }\n.bp-card {\n  background: rgba(15,21,28,0.95);\n  backdrop-filter: blur(24px);\n  border: 1px solid rgba(255,255,255,0.06);\n  border-radius: 14px;\n  padding: 28px;\n  box-shadow: 0 32px 80px rgba(0,0,0,0.4);\n  position: sticky;\n  top: 80px;\n}\n.bp-card-step {\n  display: inline-block;\n  font-size: .6875rem;\n  font-weight: 700;\n  color: var(--nx-accent, #FE9B7B);\n  background: rgba(254,155,123,0.06);\n  border: 1px solid rgba(254,155,123,0.12);\n  padding: 3px 10px;\n  border-radius: 12px;\n  margin-bottom: 16px;\n}\n.bp-card-title {\n  font-family: var(--f-display, 'Inter', sans-serif);\n  font-size: .9375rem;\n  font-weight: 700;\n  color: rgba(255,255,255,0.6);\n  margin: 0 0 14px;\n}\n\n/* Dates Grid */\n.bp-dates {\n  display: grid;\n  grid-template-columns: repeat(5, 1fr);\n  gap: 6px;\n  margin-bottom: 20px;\n}\n.bp-date {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 1px;\n  padding: 10px 4px;\n  background: rgba(12,17,23,0.5);\n  border: 1px solid rgba(255,255,255,0.04);\n  color: rgba(255,255,255,0.4);\n  cursor: pointer;\n  transition: all 250ms ease;\n  border-radius: 8px;\n}\n.bp-date:hover {\n  border-color: rgba(254,155,123,0.15);\n  transform: translateY(-2px);\n  color: rgba(255,255,255,0.7);\n}\n.bp-date.sel {\n  border-color: var(--nx-accent, #FE9B7B);\n  background: rgba(254,155,123,0.06);\n  color: #fff;\n  box-shadow: 0 0 20px rgba(254,155,123,0.06);\n}\n.bp-date-day { font-size: .5625rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; opacity: .6; }\n.bp-date-num { font-family: var(--f-display); font-size: 1.125rem; font-weight: 800; line-height: 1.2; }\n.bp-date-month { font-size: .5625rem; font-weight: 600; letter-spacing: .02em; opacity: .6; }\n\n/* Times Grid */\n.bp-times {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 6px;\n  margin-bottom: 20px;\n}\n.bp-time {\n  padding: 10px;\n  background: rgba(12,17,23,0.5);\n  border: 1px solid rgba(255,255,255,0.04);\n  color: rgba(255,255,255,0.45);\n  font-size: .875rem;\n  font-weight: 600;\n  font-family: var(--f-display);\n  text-align: center;\n  transition: all 250ms ease;\n  border-radius: 6px;\n  cursor: pointer;\n  font-variant-numeric: tabular-nums;\n}\n.bp-time:hover { border-color: rgba(254,155,123,0.15); color: rgba(255,255,255,0.7); }\n.bp-time.sel { border-color: var(--nx-accent, #FE9B7B); background: rgba(254,155,123,0.06); color: #fff; }\n.bp-no-slots { color: rgba(255,255,255,0.25); font-size: .8125rem; text-align: center; padding: 16px; }\n\n/* Back Button */\n.bp-back {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  background: none;\n  border: none;\n  color: rgba(255,255,255,0.35);\n  font-size: .75rem;\n  font-weight: 600;\n  margin-bottom: 14px;\n  padding: 0;\n  cursor: pointer;\n  transition: color 200ms;\n}\n.bp-back:hover { color: rgba(255,255,255,0.7); }\n.bp-back .material-symbols-outlined { font-size: 16px; }\n\n/* Selected Summary */\n.bp-selected {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 12px 16px;\n  background: rgba(254,155,123,0.04);\n  border: 1px solid rgba(254,155,123,0.10);\n  border-radius: 8px;\n  margin-bottom: 20px;\n}\n.bp-selected .material-symbols-outlined { font-size: 22px; color: var(--nx-accent, #FE9B7B); }\n.bp-selected strong { display: block; font-size: .8125rem; color: #fff; }\n.bp-selected span { display: block; font-size: .75rem; color: rgba(255,255,255,0.4); }\n\n/* Form Fields */\n.bp-fields { display: flex; flex-direction: column; gap: 14px; }\n.bp-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.bp-field { display: flex; flex-direction: column; gap: 4px; }\n.bp-field label {\n  font-size: .625rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: .1em;\n  color: var(--nx-accent, #FE9B7B);\n}\n.bp-field input, .bp-field textarea {\n  background: rgba(14,20,28,0.7);\n  border: 1px solid rgba(255,255,255,0.06);\n  border-radius: 6px;\n  padding: 11px 14px;\n  color: #fff;\n  font-size: .875rem;\n  font-family: var(--f-body, 'Inter', sans-serif);\n  outline: none;\n  transition: border-color 0.2s, box-shadow 0.2s;\n  width: 100%;\n  resize: vertical;\n}\n.bp-field input:focus, .bp-field textarea:focus {\n  border-color: rgba(254,155,123,0.35);\n  box-shadow: 0 0 0 3px rgba(254,155,123,0.06);\n}\n.bp-field input.err { border-color: #ef4444; }\n.bp-err { color: #ef4444; font-size: .6875rem; font-weight: 600; }\n.bp-submit-err {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 10px 14px;\n  background: rgba(239,68,68,0.06);\n  border: 1px solid rgba(239,68,68,0.15);\n  border-radius: 8px;\n  color: #ef4444;\n  font-size: .8125rem;\n}\n\n/* Buttons */\n.bp-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  width: 100%;\n  padding: 14px 24px;\n  border: none;\n  border-radius: 8px;\n  font-size: .9375rem;\n  font-weight: 700;\n  font-family: var(--f-display, 'Inter', sans-serif);\n  cursor: pointer;\n  transition: all 300ms ease;\n  text-decoration: none;\n  text-align: center;\n}\n.bp-btn-primary {\n  background: var(--nx-accent, #FE9B7B);\n  color: #0c1117;\n}\n.bp-btn-primary:hover:not(:disabled) {\n  filter: brightness(1.1);\n  transform: translateY(-1px);\n  box-shadow: 0 8px 32px rgba(254,155,123,0.2);\n}\n.bp-btn:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n.bp-spinner {\n  width: 16px;\n  height: 16px;\n  border: 2px solid rgba(12,17,23,0.2);\n  border-top-color: #0c1117;\n  border-radius: 50%;\n  animation: bp-spin .7s linear infinite;\n  margin-right: 6px;\n}\n@keyframes bp-spin { to { transform: rotate(360deg); } }\n\n/* Success */\n.bp-success { text-align: center; padding: 24px 0; }\n.bp-success-icon { margin-bottom: 16px; }\n.bp-success-icon .material-symbols-outlined { font-size: 56px; color: #34d399; }\n.bp-success h2 {\n  font-family: var(--f-display);\n  font-size: 1.5rem;\n  font-weight: 800;\n  margin: 0 0 20px;\n}\n.bp-success-detail {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-bottom: 16px;\n  padding: 16px;\n  background: rgba(255,255,255,0.02);\n  border: 1px solid rgba(255,255,255,0.04);\n  border-radius: 10px;\n}\n.bp-success-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: .875rem;\n  color: rgba(255,255,255,0.6);\n}\n.bp-success-row .material-symbols-outlined { font-size: 18px; color: var(--nx-accent, #FE9B7B); }\n.bp-success-text {\n  font-size: .875rem;\n  color: rgba(255,255,255,0.45);\n  line-height: 1.6;\n  margin-bottom: 20px;\n}\n.bp-success-next {\n  text-align: left;\n  padding: 16px;\n  background: rgba(52,211,153,0.04);\n  border: 1px solid rgba(52,211,153,0.10);\n  border-radius: 10px;\n  margin-bottom: 24px;\n}\n.bp-success-next h4 {\n  font-size: .75rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: .05em;\n  color: rgba(52,211,153,0.8);\n  margin: 0 0 10px;\n}\n.bp-success-next ul { list-style: none; padding: 0; margin: 0; }\n.bp-success-next li {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: .8125rem;\n  color: rgba(255,255,255,0.5);\n  margin-bottom: 6px;\n}\n.bp-success-next li .material-symbols-outlined { font-size: 14px; color: rgba(52,211,153,0.7); }\n\n/* Footer */\n.bp-footer {\n  border-top: 1px solid rgba(255,255,255,0.04);\n  padding: 16px 24px;\n  font-size: .75rem;\n  color: rgba(255,255,255,0.25);\n}\n.bp-footer-inner {\n  max-width: 1200px;\n  margin: 0 auto;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.bp-footer-links { display: flex; gap: 16px; }\n.bp-footer-links a { color: rgba(255,255,255,0.3); text-decoration: none; transition: color 200ms; }\n.bp-footer-links a:hover { color: rgba(255,255,255,0.6); }\n\n/* Responsive */\n@media (max-width: 900px) {\n  .bp-layout {\n    grid-template-columns: 1fr;\n    gap: 32px;\n    padding: 32px 20px 48px;\n  }\n  .bp-info { position: static; }\n  .bp-card { position: static; }\n  .bp-dates { grid-template-columns: repeat(4, 1fr); }\n}\n@media (max-width: 480px) {\n  .bp-layout { padding: 24px 16px 40px; }\n  .bp-dates { grid-template-columns: repeat(3, 1fr); }\n  .bp-times { grid-template-columns: repeat(2, 1fr); }\n  .bp-row { grid-template-columns: 1fr; }\n  .bp-card { padding: 20px; }\n}\n"],"sourceRoot":""}]);
